import { StudioProApi } from "@mendix/extensions-api";
import { createStudioProLogger } from "../config/logger";
import { Knowledgebase, Provider } from "../types/knowledgebase/knowledgebase";
import { MxCloudGenAIKnowledgebaseFields } from "../types/knowledgebase/mxCloudGenAIKnowledgebase";

export const updateKnowledgebaseDocument =
    (studioPro: StudioProApi, documentId: string) => async (knowledgebase: Knowledgebase) => {
        const logger = createStudioProLogger(studioPro);
        try {
            await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, knowledgebase);
        } catch (error) {
            logger.error("Failed to save knowledge base document:", error);
            await studioPro.ui.notifications.show({
                title: "Failed to save knowledge base document.",
                message: (error as Error).message,
            });
        }
    };

export function createNewKnowledgebase(): Knowledgebase {
    return {
        name: "",
        provider: "MxCloudGenAI" as Provider, // Preselect MxCloudGenAI as default provider
        providerFields: createNewMxCloudGenAIKnowledgebaseFields(),
    };
}

export const createNewMxCloudGenAIKnowledgebaseFields = (): MxCloudGenAIKnowledgebaseFields => {
    return {
        environment: "",
        deepLinkURL: "",
        keyId: "",
        keyName: "",
        modelDisplayName: "",
        modelName: "",
    };
};

/**
 * Clears the knowledgebase details while preserving provider-specific fields that are necessary for maintaining the connection to the provider.
 * @param knowledgebase - The knowledgebase to clear.
 * @returns The cleared knowledgebase.
 */
export const clearKnowledgebaseDetails = (knowledgebase: Knowledgebase): Knowledgebase => {
    const providerFields = knowledgebase.providerFields as MxCloudGenAIKnowledgebaseFields;

    const clearedModel = {
        ...createNewKnowledgebase(),
        provider: knowledgebase.provider,
        providerFields: {
            ...createNewMxCloudGenAIKnowledgebaseFields(),
            key: providerFields.key,
        },
    };

    return clearedModel;
};
